145	    void
146	    CHAOSCache::injectFault()
147	    {   
148	        BaseTags* tags = getTags();
149	        unsigned blockSize = targetCache->getBlockSize();
150	        
151	        std::vector<CacheBlk*> validBlocks;
152	        
153	        tags->forEachBlk([&validBlocks](CacheBlk &blk) {
154	            if (blk.isValid()) {
155	                validBlocks.push_back(&blk);
156	            }
157	        });
158	        
159	        if (validBlocks.empty()) {
160	            warn("No valid block found\n");
161	        } else{
162	            // Directed target (report §六.3 'fixed-to'): if target_block_addr
163	            // is set, find the VALID block whose regenerated address matches
164	            // the block-aligned target. If not resident at injection time,
165	            // fall back to random with a log warning (honest: the fault did
166	            // not land on the directed block because it wasn't valid).
167	            CacheBlk* targetBlk = nullptr;
168	            bool directed_block = (target_block_addr != 0);
169	            if (directed_block) {
170	                Addr blkMask = ~(static_cast<Addr>(blockSize) - 1);
171	                Addr wantBlockAddr = target_block_addr & blkMask;
172	                for (CacheBlk* blk : validBlocks) {
173	                    if (tags->regenerateBlkAddr(blk) == wantBlockAddr) {
174	                        targetBlk = blk;
175	                        break;
176	                    }
177	                }
178	                if (!targetBlk && write_log) {
179	                    *(log_stream->stream()) << "Tick: " << curTick()
180	                        << ", Directed target_block_addr=0x" << std::hex
181	                        << target_block_addr << std::dec
182	                        << " NOT resident (no valid block at that address) — "
183	                        << "falling back to random block." << std::endl;
184	                }
185	            }
186	            if (!targetBlk) {
187	                std::uniform_int_distribution<int> blockDist(0, validBlocks.size() - 1);
188	                int randomIdx = blockDist(rng);
189	                targetBlk = validBlocks[randomIdx];
190	            }
191	
192	            Addr blockAddr = tags->regenerateBlkAddr(targetBlk);
193	
194	            uint8_t* data = targetBlk->data;
195	
196	            // §7.7 paired-sector 128B fault-domain proxy: find the 128B-aligned
197	            // paired partner block (blockAddr XOR 64B). The fault is applied to
198	            // BOTH sectors at the SAME byte offset. The partner must be VALID+
199	            // resident (else only the primary is faulted — logged honestly).
200	            // This models a 128B L3 fault domain spanning two 64B sectors. It is
201	            // a PROXY, not a cycle-exact Kunpeng L3 model (per plan §7.7/§3.1).
202	            CacheBlk* partnerBlk = nullptr;
203	            uint8_t* partnerData = nullptr;
204	            Addr partnerAddr = 0;
205	            if (paired_sector) {
206	                // The partner is the other 64B sector in the same 128B superline.
207	                Addr partnerBlockAddr = blockAddr ^ blockSize;  // toggle bit (log2(64)=6)
208	                for (CacheBlk* blk : validBlocks) {
209	                    if (tags->regenerateBlkAddr(blk) == partnerBlockAddr) {
210	                        partnerBlk = blk;
211	                        partnerData = blk->data;
212	                        partnerAddr = partnerBlockAddr;
213	                        break;
214	                    }
215	                }
216	                if (write_log && !partnerBlk) {
217	                    *(log_stream->stream()) << "Tick: " << curTick()
218	                        << ", PAIRED-SECTOR WARN: partner block 0x" << std::hex
219	                        << partnerBlockAddr << std::dec << " NOT resident — "
220	                        << "only primary sector faulted (128B domain incomplete)."
221	                        << std::endl;
222	                }
223	            }
224	
225	            // Directed byte offset (report §六.3 'fixed-to'): if set, pin the
226	            // fault to this byte within the block; else random.
227	            bool directed_byte = (target_byte_offset >= 0
228	                                  && target_byte_offset < (int)blockSize);
229	
230	            FaultType chosen_fault_type_enum = fault_type_enum;
231	            if (fault_type_enum == FaultType::Random) {
232	                int faultIdx = random_fault_distribution(rng);
233	                chosen_fault_type_enum = static_cast<FaultType>(faultIdx);
234	            }
235	
236	            for (int i = 0; i < corruption_size; i++) {
237	                unsigned char mask = (fault_mask != 0) ? fault_mask : generateRandomMask(rng, bits_to_change, 8);
238	                int byteOffset;
239	                if (directed_byte) {
240	                    byteOffset = target_byte_offset;
241	                } else {
242	                    std::uniform_int_distribution<int> byteDist(0, blockSize - 1);
243	                    byteOffset = byteDist(rng);
244	                }
245	
246	                if (mask == 0) {
247	                    warn("Mask is 0.");
248	                    continue;
249	                }
250	
251	                // uint8_t oldValue = data[byteOffset];
252	
253	                switch (chosen_fault_type_enum) {
254	                    case FaultType::StuckAtZero:
255	                        data[byteOffset] &= ~mask;
256	                        stats->numStuckAtZero++;
257	                        stats->numPermanentFaults++;
258	                        permanent_faults[std::make_pair(blockAddr, byteOffset)] = {chosen_fault_type_enum, mask, true};
259	                        break;
260	                    case FaultType::StuckAtOne:
261	                        data[byteOffset] |= mask;
262	                        stats->numStuckAtOne++;
263	                        stats->numPermanentFaults++;
264	                        permanent_faults[std::make_pair(blockAddr, byteOffset)] = {chosen_fault_type_enum, mask, true};
265	                        break;
266	                    case FaultType::BitFlip:
267	                        data[byteOffset] ^= mask;
268	                        stats->numBitFlips++;
269	                        break;
270	                    default:
271	                        break;
272	                }
273	
274	                // uint8_t newValue = data[byteOffset];
275	                stats->numFaultsInjected++;
276	
277	                if (write_log){
278	                    *(log_stream->stream())  << "Tick: " << curTick()
279	                        << ", Cache Block Addr: " << blockAddr
280	                        << ", Byte Offset: " << byteOffset
281	                        << ", FaultType: " << faultTypeToString(chosen_fault_type_enum)
282	                        << ", Mask: " << std::bitset<8>(mask)
283	                        << std::endl;
284	                }
285	
286	                // §7.7 paired-sector: apply the SAME fault to the 128B-aligned
287	                // partner block's same byte offset (128B fault-domain proxy).
288	                if (paired_sector && partnerBlk) {
289	                    switch (chosen_fault_type_enum) {
290	                        case FaultType::StuckAtZero:
291	                            partnerData[byteOffset] &= ~mask;
292	                            permanent_faults[std::make_pair(partnerAddr, byteOffset)] = {chosen_fault_type_enum, mask, true};
293	                            break;
294	                        case FaultType::StuckAtOne:
295	                            partnerData[byteOffset] |= mask;
296	                            permanent_faults[std::make_pair(partnerAddr, byteOffset)] = {chosen_fault_type_enum, mask, true};
297	                            break;
298	                        case FaultType::BitFlip:
299	                            partnerData[byteOffset] ^= mask;
300	                            break;
301	                        default: break;
302	                    }
303	                    stats->numFaultsInjected++;  // count the paired fault too
304	                    if (write_log) {
305	                        *(log_stream->stream()) << "Tick: " << curTick()
306	                            << ", PAIRED Cache Block Addr: " << partnerAddr
307	                            << ", Byte Offset: " << byteOffset
308	                            << ", FaultType: " << faultTypeToString(chosen_fault_type_enum)
309	                            << ", Mask: " << std::bitset<8>(mask)
310	                            << ", superline: 0x" << std::hex
311	                            << (blockAddr & ~((Addr)2*blockSize - 1))
312	                            << std::dec << std::endl;
313	                    }
314	                }
315	            }
316	
317	            // targetBlk->setCoherenceBits(CacheBlk::DirtyBit);
318	        }
319	
320	        // G5: single-fault enforcement. Count the valid injections that
321	        // happened this attack (one per corruption_size byte). If we've
322	        // reached max_faults, STOP rescheduling. max_faults==0 = unlimited.
323	        faults_injected_count += corruption_size;
324	        if (max_faults != 0 && faults_injected_count >= max_faults) {
325	            return;  // do not reschedule
326	        }
327	
328	        // G6: next-event interval must be >= 1 clock cycle. Clamp the
329	        // geometric-sampled distance to >= 1 (it can be 0 at high p, which
330	        // made the event re-fire in the same tick infinitely).
331	        unsigned dist_cycles = inter_fault_cycles_dist(rng);
332	        if (dist_cycles < 1) dist_cycles = 1;
333	        Tick next_injection = curTick() + dist_cycles * tick_to_clock_ratio;
334	        if (next_injection <= last_tick || last_tick == 0) {
335	            scheduleAttack(next_injection);
336	        }
337	    }
