339	    void
340	    CHAOSCache::checkPermanent()
341	    {
342	        BaseTags* tags = getTags();
343	
344	        for (auto& entry : permanent_faults) {
345	            if(entry.second.update){
346	                const std::pair<Addr, int>& key = entry.first;
347	                const PermanentFault& fault = entry.second;
348	
349	                Addr blockAddr = key.first;
350	                int byteOffset = key.second;
351	                FaultType faultType = fault.fault_type;
352	                uint64_t mask = fault.mask;
353	
354	                CacheBlk* blk = nullptr;
355	                tags->forEachBlk([&](CacheBlk &b) {
356	                    Addr blkAddr = tags->regenerateBlkAddr(&b);
357	                    if (blkAddr == blockAddr && b.isValid()) {
358	                        blk = &b;
359	                    }
360	                });
361	                if (!blk) {
362	                    continue;
363	                }
364	
365	                uint8_t* data = blk->data;
366	                // uint8_t oldValue = data[byteOffset];
367	
368	                switch (faultType) {
369	                    case FaultType::StuckAtZero:
370	                        data[byteOffset] &= ~((uint8_t)mask);
371	                        break;
372	                    case FaultType::StuckAtOne:
373	                        data[byteOffset] |= ((uint8_t)mask);
374	                        break;
375	                    default:
376	                        break;
377	                }
378	            }
379	        }
380	    }
