def _is_simerr(stderr):
    if not stderr:
        return False
    low = stderr
    return any(mk in low for mk in _SIMERR_MARKERS)


def classify_run(stdout, stderr, returncode, faults_injected,
                 golden_checksum, timed_out=False):
    """Classify one run per plan §9.1 (ordered). Returns the category string
    plus a short reason (for the evidence log)."""
    out = (stdout or "") + "\n" + (stderr or "")
    out_checksum = extract_checksum(out)
    simerr = _is_simerr(stderr)

    # 1. SimulatorError: the tool/simulator itself broke. This is NOT a valid
    #    FI outcome — it means the run is invalid (gem5 panic/assert/SIGSEGV).
    if simerr:
        return ("SimulatorError",
                "gem5 panic/assert/SIGSEGV in stderr (tool failure, not a "
                 "fault outcome) — run invalid")

    # 2. Hang: exceeded the Hang timeout with no program completion (no
    #    checksum). Distinguished from Crash: Hang = never finished (timeout),
    #    Crash = finished-but-trapped/exit!=0 (below).
    if timed_out and not out_checksum:
        return ("Hang",
                "exceeded Hang timeout with no program checksum "
                 "(control-flow corruption: never completed)")

    if a == "-d" and i+1 < len(cmd):
        outdir = cmd[i+1]
faults = 0
for logname in ("fault_injections.log","main_mem_injections.log","cache_injections.log","rename_injections.log","freelist_injections.log"):
    p = os.path.join(outdir, logname) if outdir else None
    if p and os.path.exists(p):
        with open(p) as lf:
            for line in lf:
                # explicit count (CHAOSMem G5 evidence log)
                if "faults_injected:" in line:
                    try:
                        faults = int(line.split("faults_injected:")[1].split()[0])
                    except Exception:
                        pass
                    continue
                # CHAOSPhysReg: exclude ReadTrace* poll lines (not injections)
                if line.startswith("ReadTracePoll") or line.startswith("ReadTraceFinal"):
                    continue
                # CHAOSReg: exclude the DIRECTED info line (it's an advisory,
                # not an injection; the actual injection is the next "Cycle:"
                # line with "Register:"/"FaultType:").
                if "DIRECTED reg:" in line:
                    continue
                # count valid injection lines: exclude Inactive/Error
                if ("Inactive" in line) or line.startswith("Error"):
                    continue
                if line.strip():
                    faults += 1
        break
# G5 assertion: exactly 0 or 1 valid injection

